/** The publish rule (spec §2 + 28 Aug): dated activity inside 12 months, centres Black queer people, and does not state an audience that excludes men. */
export const publishedPlaces = (): Place[] =>
  places.filter((p) => p.status === 'live' && !p.excludesMen && ['black-queer-men', 'black-lgbtq', 'qtipoc'].includes(p.centres));

/** Entries in the file that are not shown — the Note reports this count. */
export const heldPlacesCount = (): number => places.length - publishedPlaces().length;
